[{"order":1,"type":"heading","text":"Authentication Strategies in Node.js: Local and OAuth (Passport.js)"},{"order":2,"type":"paragraph","text":"This tutorial explores two common authentication strategies for Node.js applications: local authentication (using a username and password stored in your database) and OAuth (delegating authentication to a third-party provider like Google or Facebook) using Passport.js."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js and npm installed"},{"order":5,"type":"bullet_point","text":"Basic understanding of Express.js"},{"order":6,"type":"bullet_point","text":"A code editor"},{"order":7,"type":"subheading","text":"Setting up the Project"},{"order":8,"type":"paragraph","text":"Create a new Node.js project and initialize npm:"},{"order":9,"type":"code","text":"mkdir node-auth
cd node-auth
npm init -y"},{"order":10,"type":"paragraph","text":"Install the necessary packages:"},{"order":11,"type":"code","text":"npm install express express-session passport passport-local bcryptjs mongoose"},{"order":12,"type":"paragraph","text":"Explanation of packages:
- express: Web framework for Node.js
- express-session: Middleware for managing user sessions
- passport: Authentication middleware for Node.js
- passport-local: Strategy for local username/password authentication
- bcryptjs: Library for hashing passwords
- mongoose: MongoDB object modeling tool"},{"order":13,"type":"subheading","text":"Local Authentication"},{"order":14,"type":"paragraph","text":"1. **Database Setup (MongoDB with Mongoose):**"},{"order":15,"type":"paragraph","text":"Define a User model using Mongoose. Create a 'models/User.js' file:"},{"order":16,"type":"code","text":"const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');

const UserSchema = new mongoose.Schema({
  username: {
    type: String,
    required: true,
    unique: true
  },
  password: {
    type: String,
    required: true
  }
});

UserSchema.pre('save', async function(next) {
  if (!this.isModified('password')) {
    return next();
  }

  const salt = await bcrypt.genSalt(10);
  this.password = await bcrypt.hash(this.password, salt);
  next();
});

UserSchema.methods.comparePassword = async function(enteredPassword) {
  return await bcrypt.compare(enteredPassword, this.password);
};

module.exports = mongoose.model('User', UserSchema);"},{"order":17,"type":"paragraph","text":"2. **Passport Configuration:**"},{"order":18,"type":"paragraph","text":"Create a 'config/passport.js' file to configure Passport.js for local authentication:"},{"order":19,"type":"code","text":"const passport = require('passport');
const LocalStrategy = require('passport-local').Strategy;
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');

const User = require('../models/User');

module.exports = function(passport) {
  passport.use(
    new LocalStrategy({ usernameField: 'username' }, (username, password, done) => {
      // Match user
      User.findOne({ username: username })
        .then(user => {
          if (!user) {
            return done(null, false, { message: 'That username is not registered' });
          }

          // Match password
          bcrypt.compare(password, user.password, (err, isMatch) => {
            if (err) throw err;
            if (isMatch) {
              return done(null, user);
            } else {
              return done(null, false, { message: 'Password incorrect' });
            }
          });
        })
        .catch(err => console.log(err));
    })
  );

  passport.serializeUser((user, done) => {
    done(null, user.id);
  });

  passport.deserializeUser((id, done) => {
    User.findById(id, (err, user) => {
      done(err, user);
    });
  });
};"},{"order":20,"type":"paragraph","text":"3. **Express App Setup:**"},{"order":21,"type":"paragraph","text":"In your main app file (e.g., 'app.js' or 'server.js'), configure Express, sessions, and Passport:"},{"order":22,"type":"code","text":"const express = require('express');
const expressLayouts = require('express-ejs-layouts');
const mongoose = require('mongoose');
const passport = require('passport');
const flash = require('connect-flash');
const session = require('express-session');

const app = express();

// Passport Config
require('./config/passport')(passport);

// DB Config
const db = require('./config/keys').MongoURI;

// Connect to MongoDB
mongoose
  .connect(
    db,
    { useNewUrlParser: true, useUnifiedTopology: true }
  )
  .then(() => console.log('MongoDB Connected'))
  .catch(err => console.log(err));

// Express body parser
app.use(express.urlencoded({ extended: true }));

// Express session
app.use(
  session({
    secret: 'secret',
    resave: true,
    saveUninitialized: true
  })
);

// Passport middleware
app.use(passport.initialize());
app.use(passport.session());

// Connect flash
app.use(flash());

// Global variables
app.use(function(req, res, next) {
  res.locals.success_msg = req.flash('success_msg');
  res.locals.error_msg = req.flash('error_msg');
  res.locals.error = req.flash('error');
  next();
});

// Routes
app.use('/', require('./routes/index.js'));
app.use('/users', require('./routes/users.js'));

const PORT = process.env.PORT || 5000;

app.listen(PORT, console.log(`Server started on port ${PORT}`));"},{"order":23,"type":"paragraph","text":"4. **User Registration and Login Routes:**"},{"order":24,"type":"paragraph","text":"Create routes for user registration and login.  Example 'routes/users.js':"},{"order":25,"type":"code","text":"const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const passport = require('passport');
// Load User model
const User = require('../models/User');

// Register
router.get('/register', (req, res) => res.send('Register'));

// Register
router.post('/register', (req, res) => {
  const { username, password, password2 } = req.body;
  let errors = [];

  if (!username || !password || !password2) {
    errors.push({ msg: 'Please enter all fields' });
  }

  if (password != password2) {
    errors.push({ msg: 'Passwords do not match' });
  }

  if (password.length < 6) {
    errors.push({ msg: 'Password must be at least 6 characters' });
  }

  if (errors.length > 0) {
    res.send({
      errors,
      username,
      password,
      password2
    });
  } else {
    // Validation passed
    User.findOne({ username: username }).then(user => {
      if (user) {
        errors.push({ msg: 'Username already exists' });
        res.send({
          errors,
          username,
          password,
          password2
        });
      } else {
        const newUser = new User({
          username,
          password
        });

        bcrypt.genSalt(10, (err, salt) => {
          bcrypt.hash(newUser.password, salt, (err, hash) => {
            if (err) throw err;
            newUser.password = hash;
            newUser
              .save()
              .then(user => {
                req.flash(
                  'success_msg',
                  'You are now registered and can log in'
                );
                res.send('Registration Successful');
              })
              .catch(err => console.log(err));
          });
        });
      }
    });
  }
});

// Login
router.post('/login', (req, res, next) => {
  passport.authenticate('local', {
    successRedirect: '/dashboard',
    failureRedirect: '/login',
    failureFlash: true
  })(req, res, next);
});

// Logout
router.get('/logout', (req, res) => {
  req.logout();
  req.flash('success_msg', 'You are logged out');
  res.redirect('/login');
});

module.exports = router;"},{"order":26,"type":"subheading","text":"OAuth Authentication (Passport.js)"},{"order":27,"type":"paragraph","text":"This section demonstrates OAuth 2.0 authentication using Passport.js with Google as the provider. You'll need to create a Google Cloud project and obtain OAuth 2.0 client credentials."},{"order":28,"type":"paragraph","text":"1. **Install Passport Google OAuth 2.0 Strategy:**"},{"order":29,"type":"code","text":"npm install passport-google-oauth20"},{"order":30,"type":"paragraph","text":"2. **Configure Passport for Google OAuth 2.0:**"},{"order":31,"type":"paragraph","text":"Modify 'config/passport.js' to include the Google strategy:"},{"order":32,"type":"code","text":"const GoogleStrategy = require('passport-google-oauth20').Strategy;

module.exports = function(passport) {
  passport.use(
    new GoogleStrategy(
      {
        clientID: 'YOUR_GOOGLE_CLIENT_ID',
        clientSecret: 'YOUR_GOOGLE_CLIENT_SECRET',
        callbackURL: '/auth/google/callback'
      },
      (accessToken, refreshToken, profile, done) => {
        // Get user data from Google
        const newUser = {
          googleId: profile.id,
          displayName: profile.displayName,
          firstName: profile.name.givenName,
          lastName: profile.name.familyName,
          image: profile.photos[0].value,
          email: profile.emails[0].value
        }

        // Check if user exists
        User.findOne({ googleId: profile.id }).then(user => {
          if (user) {
            // If user exists, return user
            done(null, user);
          } else {
            // If user does not exist, create user
            new User(newUser).save().then(user => done(null, user));
          }
        });
      }
    )
  );

  passport.serializeUser((user, done) => {
    done(null, user.id);
  });

  passport.deserializeUser((id, done) => {
    User.findById(id, (err, user) => {
      done(err, user);
    });
  });
};"},{"order":33,"type":"paragraph","text":"Replace 'YOUR_GOOGLE_CLIENT_ID' and 'YOUR_GOOGLE_CLIENT_SECRET' with your actual Google OAuth 2.0 credentials."},{"order":34,"type":"paragraph","text":"3. **Create Google Authentication Routes:**"},{"order":35,"type":"paragraph","text":"Add routes for initiating the Google authentication flow and handling the callback. Modify 'routes/index.js':"},{"order":36,"type":"code","text":"const express = require('express');
const router = express.Router();
const { ensureAuthenticated, forwardAuthenticated } = require('../config/auth');
const passport = require('passport');

// Google Auth Routes
router.get('/auth/google',
  passport.authenticate('google', { scope: ['profile', 'email'] }));

router.get('/auth/google/callback',
  passport.authenticate('google', { failureRedirect: '/login' }),
  function(req, res) {
    // Successful authentication, redirect home.
    res.redirect('/dashboard');
  });

// Dashboard
router.get('/dashboard', ensureAuthenticated, (req, res) =>
  res.send('Welcome ' + req.user.username)
);

module.exports = router;"},{"order":37,"type":"paragraph","text":"4. **Update User Model:**"},{"order":38,"type":"paragraph","text":"Update the User model ('models/User.js') to include fields for Google authentication (googleId, displayName, etc.)."},{"order":39,"type":"code","text":"const mongoose = require('mongoose');

const UserSchema = new mongoose.Schema({
  googleId: {
    type: String
  },
  displayName: {
    type: String
  },
  firstName: {
    type: String
  },
  lastName: {
    type: String
  },
  image: {
    type: String
  },
  email: {
    type: String
  },
  username: {
    type: String
  },
  password: {
    type: String
  },
  date: {
    type: Date,
    default: Date.now
  }
});

const User = mongoose.model('User', UserSchema);

module.exports = User;"},{"order":40,"type":"subheading","text":"Conclusion"},{"order":41,"type":"paragraph","text":"This tutorial covered local authentication and OAuth with Passport.js in Node.js. You can adapt these strategies to other authentication providers and customize them to fit your application's specific needs."}]
